jQuery(document).ready(function($){$('#cos-slider-carrousel').lightGallery({selector:'#cos-slider-carrousel A.project-slide-item',thumbnail:!0,animateThumb:!1,loop:!1,showThumbByDefault:!0,download:!1,googlePlus:!1,});$('#cos-slider-carrousel .btn-expand').click(function(e){let $gallery=$(this).closest('.slider-carousel');$gallery.find('A.slick-active').click()});const carousels=document.querySelectorAll('#cos-slider-carrousel .slider-container');if(!carousels||carousels.length===0){return}
carousels.forEach((element)=>{const arrowLeft=element.parentElement.querySelector('#cos-slider-carrousel .btn-prev');const arrowRight=element.parentElement.querySelector('#cos-slider-carrousel .btn-next');const slickOptions={infinite:!1,autoplay:!1,dots:!1,arrows:!0,fade:!1,centerMode:!1,prevArrow:arrowLeft,nextArrow:arrowRight,slidesToShow:1,slidesToScroll:1};const slickedElement=$(element).slick(slickOptions);window.addEventListener('resize',function(e){if(!slickedElement.hasClass('slick-initialized')){slickedElement.slick(slickOptions)}})})})